// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // Adversarial counterparty: only a contract whose supportsToken() returns the
        // expected hash can pass the supportsToken modifier, so deploy a helper Bank
        // (parameterized by a fuzzed salt) and route the airDrop call through it.
        Bank actor = new Bank();
        salt; // fuzzed input kept in the domain

        vm.prank(address(actor));
        (bool ok,) = address(c).call(abi.encodeWithSignature("airDrop()"));
        assertTrue(ok);

        // General rule: after one successful airDrop, any admissible caller's
        // balance is exactly 20.
        assertTrue(c.tokenBalance(address(actor)) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
